#!/usr/bin/env python3
"""Build the existing landing page and focused, static informational pages."""
from pathlib import Path
from html import escape
from copy import deepcopy
import re,json,hashlib,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
BASE='https://guara-tickets.vercel.app'
HOME=(ROOT/'src/home.html').read_text()
DATE='2026-11-04'
CSS=re.search(r'<style>(.*?)</style>',HOME,re.S)[1]
EXTRA='''
html{scroll-padding-top:24px}.hero h1.seo-heading{font-size:clamp(36px,4.4vw,58px);letter-spacing:-2px;line-height:1.08;margin:18px 0}.hero-copy>p.hero-tagline{font-size:13px;font-weight:800;letter-spacing:.08em;margin:20px 0 0}.page-hero{background:var(--yellow);padding:44px 0 40px}.page-hero h1{font-size:clamp(32px,4.4vw,55px);line-height:1.1;letter-spacing:-1.5px;max-width:900px;margin:18px 0}.page-hero .intro{font-size:17px;line-height:1.65;max-width:790px;margin:0}.breadcrumb{display:flex;gap:8px;flex-wrap:wrap;font-size:12px;line-height:1.6}.breadcrumb a{text-decoration:underline;text-underline-offset:3px}.page-body{padding:44px 0 60px}.reading-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:40px;align-items:start}.reading-layout>*,.service-grid>*{min-width:0}.prose h2{font-size:30px;line-height:1.2;letter-spacing:-.8px;margin:34px 0 18px}.prose h3{font-size:20px;line-height:1.3;margin:25px 0 12px}.prose p,.prose li{font-size:16px;line-height:1.8;color:#4e493f}.prose p{margin:0 0 18px}.prose ul,.prose ol{padding-left:24px;margin:14px 0 24px}.prose li{margin:8px 0}.prose a:not(.btn){text-decoration:underline;text-underline-offset:3px;font-weight:700}.prose .btn{color:white}.prose .btn.yellow{color:var(--ink)}.info-panel{border:1px solid #d9d5c8;border-radius:12px;padding:24px;background:white}.info-panel h2{font-size:23px;margin:0 0 16px;letter-spacing:-.4px;line-height:1.2}.info-panel p{font-size:14px;line-height:1.75;color:#4e493f;margin:0 0 16px}.info-panel .btn{width:100%;padding:14px;font-size:13px}.related-links{display:grid;gap:6px;margin-top:18px}.related-links a{display:flex;align-items:center;min-height:44px;text-decoration:underline;text-underline-offset:3px;font-size:14px;font-weight:700}.service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:28px}.service-card{display:block;background:white;border:1px solid #d9d5c8;border-radius:10px;padding:23px;min-height:170px;transition:box-shadow .2s}.service-card:hover,.service-card:focus-visible{box-shadow:0 6px 20px #17171715}.service-card h3{font-size:21px;letter-spacing:-.4px;line-height:1.25;margin:0 0 12px}.service-card p{color:#5b5548;font-size:14px;line-height:1.7;margin:0}.service-card .card-link{display:block;font-weight:700;font-size:13px;margin-top:17px}.about-intro{max-width:820px;font-size:16px;line-height:1.8;color:#4e493f}.quick-facts{display:flex;gap:12px 24px;flex-wrap:wrap;font-size:14px;margin-top:22px}.quick-facts strong{display:block}.site-links{display:flex;gap:8px 22px;flex-wrap:wrap;padding-top:22px;margin-top:22px;border-top:1px solid #ffffff30}.site-links a{display:inline-flex;align-items:center;min-height:44px;font-size:12px;text-decoration:underline;text-underline-offset:4px}.mobile-menu{display:none}.notice{border-left:3px solid #b18c16;padding:15px 18px;background:#fff4bd;border-radius:0 7px 7px 0;margin:22px 0}.notice p:last-child{margin-bottom:0}.example-table{width:100%;border-collapse:collapse;margin:22px 0}.example-table th,.example-table td{text-align:left;border-bottom:1px solid #d9d5c8;padding:12px 8px;font-size:14px;line-height:1.5}.example-table th{background:#fff4bd}.table-scroll{overflow-x:auto}.skip-link{position:absolute;left:12px;top:-100px;background:white;padding:14px;z-index:50;text-decoration:underline}.skip-link:focus{top:10px}.page-body>.wrap>.section,.page-body>.wrap>.sim-section{margin-top:28px}.page-body>.wrap>.section{padding:28px 0}.page-body>.wrap>.sim-section{border-radius:12px;overflow:hidden}.page-body>.wrap>.sim-section>.wrap{width:calc(100% - 40px)}
@media(max-width:1000px){.service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.reading-layout{gap:24px;grid-template-columns:minmax(0,1.6fr) minmax(210px,1fr)}}
@media(max-width:720px){.hero h1.seo-heading{font-size:clamp(30px,8vw,39px);letter-spacing:-1px;line-height:1.1;margin:16px 0}.hero-copy>p.hero-tagline{font-size:11px;margin-top:18px}.page-hero{padding:28px 0 30px}.page-hero h1{font-size:33px;letter-spacing:-1px;overflow-wrap:break-word}.page-hero .intro{font-size:15px}.page-body{padding:28px 0 38px}.reading-layout{grid-template-columns:1fr;gap:25px}.prose h2{font-size:26px;margin-top:28px}.prose p,.prose li{font-size:15px;line-height:1.8}.service-grid{grid-template-columns:1fr;gap:12px;margin-top:22px}.service-card{min-height:0;padding:21px}.service-card h3{font-size:20px}.about-intro{font-size:15px}.mobile-menu{display:block;position:relative;border:0;margin-left:auto}.mobile-menu>summary{font-size:13px;min-height:44px;padding:11px 15px;border:1px solid #17171770;border-radius:6px;line-height:20px}.mobile-menu>summary:after{content:none}.mobile-menu[open]>summary{background:var(--ink);color:var(--yellow)}.mobile-menu nav{position:absolute;right:0;top:52px;z-index:30;background:var(--paper);border:1px solid #d9d5c8;border-radius:8px;box-shadow:0 8px 24px #0002;width:min(300px,calc(100vw - 36px));max-height:70vh;overflow:auto;padding:10px}.mobile-menu nav a{display:flex;align-items:center;min-height:44px;padding:9px 12px;font-size:14px;font-weight:700;border-radius:4px}.mobile-menu nav a:focus-visible,.mobile-menu nav a:hover{background:var(--yellow)}.nav .brand-logo{max-width:54vw}.quick-facts{font-size:13px}.site-links{gap:4px 18px}.site-links a{font-size:12px}.example-table th,.example-table td{font-size:12px;padding:12px 5px}.page-body>.wrap>.sim-section>.wrap{width:calc(100% - 28px)}}
@media(prefers-reduced-motion:reduce){.service-card{transition:none}}
'''
css=CSS+EXTRA
cssname='site-'+hashlib.sha256(css.encode()).hexdigest()[:10]+'.css'
(OUT/'assets'/cssname).write_text(css)
# Extract the established simulator unchanged; it remains the single calculation source.
calc=re.findall(r'<script>(.*?)</script>',HOME,re.S)[0]
(OUT/'assets/simulador.js').write_text(calc.strip()+'\n')
ui="document.querySelectorAll('.mobile-menu a').forEach(a=>a.addEventListener('click',()=>{a.closest('details').open=false}));\n"
(OUT/'assets/navegacao.js').write_text(ui)
org=json.loads(re.search(r'<script type="application/ld\+json">(.*?)</script>',HOME,re.S)[1])
org['image']=BASE+'/assets/compartilhamento-guara.png'
org['description']='Atendimento de VR, vale-alimentação, vale-refeição e cartões de benefícios com Israel, proprietário do Guará Mix, no Jardim Umarizal/Campo Limpo, São Paulo. Região sul, centro e zona oeste da capital.'
WA_ICON=re.search(r'(<svg class="wa-icon".*?</svg>)',HOME,re.S)[1]
WA='https://wa.me/5511940240988'
def wa(label='Falar com Israel',cls='btn',message=None):
 from urllib.parse import quote
 href=WA+('?text='+quote(message) if message else '')
 return f'<a class="{cls}" href="{href}" target="_blank" rel="noopener">{escape(label)} {WA_ICON}</a>'
links=[('/', 'Início'),('/vender-vr/','VR e cartões'),('/vale-refeicao/','Vale-refeição'),('/vale-alimentacao/','Vale-alimentação'),('/taxas/','Taxas e simulador'),('/como-funciona/','Como funciona'),('/atendimento-sao-paulo/','Atendimento em São Paulo'),('/duvidas/','Dúvidas'),('/sobre/','Quem atende')]
header=re.search(r'<header>.*?</header>',HOME,re.S)[0].replace('href="#inicio"','href="/"').replace('src="assets/','src="/assets/').replace('href="#taxas"','href="/taxas/"').replace('href="#como-funciona"','href="/como-funciona/"')
menu='<details class="mobile-menu"><summary>Menu</summary><nav aria-label="Navegação pelo site">'+''.join(f'<a href="{u}">{t}</a>'for u,t in links)+'</nav></details>'
header=header.replace('</nav></header>',menu+'</nav></header>')
top=re.search(r'<div class="topbar">.*?</div>',HOME,re.S)[0]
footer=re.search(r'<footer>.*?</footer>',HOME,re.S)[0].replace('src="assets/','src="/assets/').replace('href="#inicio"','href="/"')
flinks=links[1:]+[('/condicoes/','Condições do atendimento'),('/privacidade/','Privacidade')]
footer=footer.replace('</footer>','<nav class="wrap site-links" aria-label="Informações e páginas do site">'+''.join(f'<a href="{u}">{t}</a>'for u,t in flinks)+'</nav></footer>')
fixed=re.search(r'<a class="btn mobile-contact".*?</a>',HOME,re.S)[0]
headbase=HOME[HOME.index('<head>')+6:HOME.index('<style>')]
headbase=re.sub(r'<script type="application/ld\+json">.*?</script>','',headbase,flags=re.S)
def schema(path,title):
 url=BASE+path
 graph=[deepcopy(org),{'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':'Guará Tickets','inLanguage':'pt-BR','publisher':{'@id':org['@id']}},{'@type':'WebPage','@id':url+'#pagina','url':url,'name':title,'inLanguage':'pt-BR','isPartOf':{'@id':BASE+'/#website'},'about':{'@id':org['@id']}}]
 if path!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Início','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title.split(' | ')[0],'item':url}]})
 return '<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False,separators=(',',':'))+'</script>'
def head(path,title,desc,noindex=False):
 h=re.sub(r'<title>.*?</title>','<title>'+escape(title)+'</title>',headbase,flags=re.S)
 for attr,val in [('name="description"',desc),('property="og:title"',title),('property="og:description"',desc),('name="twitter:title"',title),('name="twitter:description"',desc),('property="og:url"',BASE+path)]:
  h=re.sub(r'(<meta '+re.escape(attr)+r' content=")[^"]*(">)',lambda m:m[1]+escape(val,quote=True)+m[2],h)
 h=re.sub(r'(<link rel="canonical" href=")[^"]*(">)',lambda m:m[1]+BASE+path+m[2],h)
 h+='<meta name="robots" content="'+('noindex,follow'if noindex else'index,follow,max-image-preview:large')+'">\n'
 h+=f'<link rel="stylesheet" href="/assets/{cssname}">\n'
 return '<head>'+h+(''if noindex else schema(path,title))+'</head>'
def layout(path,title,desc,main,hascalc=False,noindex=False):
 scripts='<script src="/assets/navegacao.js" defer></script>'
 if hascalc:scripts+='<script src="/assets/simulador.js" defer></script>'
 return '<!doctype html><html lang="pt-BR">'+head(path,title,desc,noindex)+'<body><a class="skip-link" href="#conteudo">Pular para o conteúdo</a>'+top+header+'<main id="conteudo">'+main+'</main>'+footer+fixed+scripts+'</body></html>'
def hero(title,intro,label):return f'<section class="page-hero"><div class="wrap"><nav class="breadcrumb" aria-label="Caminho da página"><a href="/">Início</a><span aria-hidden="true">/</span><span>{escape(label)}</span></nav><h1>{title}</h1><p class="intro">{intro}</p></div></section>'
def sidebar():return '<aside class="info-panel"><h2>Atendimento com Israel</h2><p>Proprietário do Guará Mix, no Jardim Umarizal/Campo Limpo, São Paulo — SP.</p><p>Somente região sul, centro e zona oeste da capital. Agende com no mínimo 3 dias de antecedência. Pagamento somente via Pix.</p>'+wa()+'<nav class="related-links" aria-label="Continue sua consulta"><a href="/taxas/">Confira as taxas e simule</a><a href="/como-funciona/">Veja como agendar</a><a href="/atendimento-sao-paulo/">Confira a área atendida</a><a href="/condicoes/">Leia as condições do atendimento</a></nav></aside>'
def prose(body):return '<section class="page-body"><div class="wrap reading-layout"><div class="prose">'+body+'</div>'+sidebar()+'</div></section>'
def extract(id):return re.search(r'<section[^>]*id="'+re.escape(id)+r'".*?</section>',HOME,re.S)[0].replace('src="assets/','src="/assets/')
faq=re.findall(r'<details>.*?</details>',extract('como-funciona'),re.S)
rate_table=re.search(r'<table class="rate-table">.*?</table>',HOME,re.S)[0]
examples='''<div class="table-scroll"><table class="example-table"><caption>Exemplos para alimentação e refeição</caption><thead><tr><th scope="col">Valor bruto</th><th scope="col">Taxa</th><th scope="col">Desconto</th><th scope="col">Você recebe</th></tr></thead><tbody><tr><td>R$ 1.000,00</td><td>17%</td><td>R$ 170,00</td><td>R$ 830,00</td></tr><tr><td>R$ 1.500,00</td><td>16%</td><td>R$ 240,00</td><td>R$ 1.260,00</td></tr><tr><td>R$ 2.500,00</td><td>15%</td><td>R$ 375,00</td><td>R$ 2.125,00</td></tr></tbody></table></div>'''
PAGES={}
def page(slug,title,h1,intro,body):PAGES['/'+slug+'/']={'title':title+' | Guará Tickets','h1':h1,'desc':intro,'main':hero(h1,intro,title)+prose(body),'calc':False}
page('vender-vr','VR em São Paulo: modalidades, taxas e consulta','VR em São Paulo: consulte sua modalidade e o valor a receber','Veja as informações para consultar VR Alimentação e VR Refeição com Israel. Atendimento na região sul, centro e zona oeste de São Paulo.', '''<h2>Primeiro, identifique a modalidade do cartão</h2><p>VR é uma das bandeiras apresentadas pela Guará Tickets. Na consulta, informe se o cartão é de alimentação ou refeição. A bandeira e a modalidade ajudam Israel a confirmar a disponibilidade e as condições do atendimento.</p><p>Também são mencionadas Ticket, Alelo e Pluxee. Não existe aprovação automática pelo site: a confirmação é feita pelo WhatsApp.</p><h2>O que informar na primeira mensagem</h2><ol><li>Nome da bandeira e modalidade do cartão.</li><li>Valor que pretende consultar em cada cartão e o total.</li><li>Região de São Paulo e data pretendida para o atendimento.</li></ol><p>Você não precisa inserir número de cartão, senha ou código de segurança no site. O simulador pede somente o tipo de benefício e o valor.</p><h2>Como o total define a taxa</h2><p>Para alimentação e refeição, as faixas anunciadas são 17% até R$ 1.000,00; 16% de R$ 1.000,01 a R$ 2.000,00; e 15% acima de R$ 2.000,00. A faixa é aplicada ao valor total, e não somente à parte que ultrapassa o limite.</p><p>Por exemplo, R$ 1.500,00 correspondem à faixa de 16%: o desconto é de R$ 240,00 e o recebimento estimado é de R$ 1.260,00. <a href="/taxas/">Veja outros exemplos e use o simulador.</a></p><h2>Agendamento e local</h2><p>Agende com pelo menos 3 dias de antecedência. A base do atendimento é o Guará Mix, no Jardim Umarizal/Campo Limpo. A cobertura é somente região sul, centro e zona oeste da capital. Atendimento no local do cliente tem taxa de motoboy combinada à parte.</p><h2>Continue pela modalidade</h2><ul><li><a href="/vale-refeicao/">Informações sobre vale-refeição.</a></li><li><a href="/vale-alimentacao/">Informações sobre vale-alimentação e soma de cartões.</a></li><li><a href="/condicoes/">Condições comerciais e confirmação antes do atendimento.</a></li></ul>''')
page('vale-refeicao','Vale-refeição em São Paulo: cartões e atendimento','Vale-refeição: cartões, taxas e atendimento em São Paulo','Consulte sua modalidade de vale-refeição, entenda o cálculo do valor líquido e saiba o que combinar antes do atendimento.', '''<h2>Vale-refeição e bandeira são informações diferentes</h2><p>O nome da bandeira, como VR, Ticket, Alelo ou Pluxee, identifica a marca do cartão. A modalidade informa se o benefício é de refeição ou alimentação. Na primeira consulta, envie as duas informações para Israel confirmar o atendimento.</p><p>Vale-refeição é normalmente associado a refeições prontas. Se o seu cartão tem mais de uma modalidade, informe qual saldo deseja consultar; não presuma que todos os saldos ou produtos de uma mesma marca têm as mesmas condições.</p><h2>O cálculo usa o valor bruto informado</h2><p>A faixa da taxa anunciada depende do total dos cartões de alimentação e refeição. Em um total de R$ 1.000,00, a taxa é 17%, equivalente a R$ 170,00, e o valor estimado a receber é R$ 830,00. Se o total for R$ 1.500,00, a faixa passa a 16%, com estimativa de R$ 1.260,00 recebidos.</p><p><a href="/taxas/">Confira a tabela completa e faça sua própria simulação.</a> A estimativa não substitui a confirmação das condições pelo WhatsApp.</p><h2>Checklist antes de sair de casa</h2><ul><li>Confirme a disponibilidade para a bandeira e modalidade.</li><li>Combine valor bruto, desconto e valor líquido.</li><li>Agende com pelo menos 3 dias de antecedência e confirme o local.</li><li>Se o atendimento for até você, confirme a taxa de motoboy.</li><li>Combine o recebimento, que é somente via Pix.</li></ul><h2>Quem responde e qual é a cobertura?</h2><p>Israel, proprietário do Guará Mix, realiza o atendimento. Estamos no Jardim Umarizal/Campo Limpo e atendemos somente a região sul, o centro e a zona oeste de São Paulo — SP.</p><p>Para outra modalidade, consulte a página de <a href="/vale-alimentacao/">vale-alimentação</a>. Para entender o fluxo completo, veja <a href="/como-funciona/">como funciona o atendimento</a>.</p>''')
page('vale-alimentacao','Vale-alimentação em São Paulo: total dos cartões e taxas','Vale-alimentação: entenda o total dos cartões e as taxas','Veja como organizar sua consulta de vale-alimentação e calcular a estimativa considerando vários cartões no mesmo atendimento.', '''<h2>Informe o saldo da modalidade correta</h2><p>Vale-alimentação é normalmente associado à compra de gêneros alimentícios. Se o seu cartão também tem outras modalidades ou saldos, identifique qual deles está consultando. O nome da bandeira sozinho não define todas as condições.</p><p>VR, Ticket, Alelo e Pluxee são as bandeiras apresentadas para alimentação e refeição. A disponibilidade da modalidade precisa ser confirmada com Israel pelo WhatsApp.</p><h2>Como funciona a soma de cartões</h2><p>Para a tabela de alimentação e refeição, o que define a faixa é o valor total dos cartões do atendimento. Você pode informar os valores separados para facilitar a conferência.</p><p>Exemplo: um cartão de R$ 600,00 e outro de R$ 700,00 totalizam R$ 1.300,00. Esse total está na faixa de 16%. O desconto estimado é de R$ 208,00 e o valor líquido é de R$ 1.092,00.</p><p>A tabela é: 17% até R$ 1.000,00; 16% de R$ 1.000,01 a R$ 2.000,00; 15% acima de R$ 2.000,00. <a href="/taxas/">Abra o simulador para conferir outro total.</a></p><h2>O que confirmar no agendamento</h2><p>Confirme a bandeira, a modalidade, o valor bruto e o valor líquido com Israel. As taxas anunciadas consideram agendamento com pelo menos 3 dias de antecedência. Sem agendamento, a taxa é maior e deve ser consultada.</p><p>O pagamento é somente via Pix. Atendimento no local do cliente tem taxa de motoboy, combinada antes. A cobertura é somente região sul, centro e zona oeste de São Paulo.</p><h2>Outros benefícios têm outra condição</h2><p>iFood, Swile, Flash e Caju aparecem no grupo de outros benefícios, com taxa anunciada de 15% e disponibilidade sujeita à modalidade. Não misture esse grupo com a tabela de alimentação e refeição sem confirmar com Israel.</p><p>Leia as <a href="/condicoes/">condições do atendimento</a> e as informações de <a href="/vale-refeicao/">vale-refeição</a> se essa for a modalidade do seu cartão.</p>''')
page('como-funciona','Como funciona: consulta, agendamento e Pix','Como funciona o atendimento da Guará Tickets','Da primeira conversa com Israel à confirmação do valor e do local: veja o que combinar em cada etapa.', '''<h2>1. Faça a consulta pelo WhatsApp</h2><p>O atendimento é realizado por Israel, proprietário do Guará Mix. Informe a bandeira, a modalidade e o valor pretendido. Se tiver vários cartões, informe os valores de cada um e o total.</p><p>Para organizar o atendimento, informe também sua região de São Paulo e a data desejada. O site não tem cadastro nem pagamento online.</p><h2>2. Confirme a taxa e o valor líquido</h2><p>Antes de agendar, confirme quanto será passado, quanto será descontado e quanto você receberá. O <a href="/taxas/">simulador</a> ajuda a estimar os valores de alimentação, refeição e outros benefícios, mas a confirmação é feita no atendimento.</p><p>Na modalidade de cartão de crédito, a taxa anunciada de 15% é descontada do valor bruto. R$ 1.000,00 passados correspondem a R$ 150,00 de taxa e R$ 850,00 recebidos. Condições do cartão devem ser combinadas com Israel.</p><h2>3. Agende com pelo menos 3 dias de antecedência</h2><p>Combine data, horário e local. As taxas da página consideram esse agendamento. Sem agendamento, a taxa é maior e deve ser consultada antes.</p><p>A base é o Jardim Umarizal/Campo Limpo. Atendemos somente a região sul, o centro e a zona oeste da capital. Se o atendimento for até você, confirme separadamente a disponibilidade e a taxa de motoboy.</p><h2>4. Confira os valores no atendimento</h2><p>Confira os valores combinados e o canal de recebimento. O pagamento é feito no ato, somente via Pix.</p><h2>O que o site não solicita</h2><p>O simulador não solicita número de cartão, senha, código de segurança, foto de documento ou dados bancários. Ele precisa apenas da categoria e do valor para calcular a estimativa.</p><p><a href="/condicoes/">Leia as condições comerciais</a> e <a href="/privacidade/">saiba como os dados do simulador e dos links são usados</a>.</p>''')
page('atendimento-sao-paulo','Atendimento em São Paulo: Campo Limpo e regiões','Atendimento em São Paulo: região sul, centro e zona oeste','Nossa base fica no Jardim Umarizal, na região do Campo Limpo. Consulte a disponibilidade com Israel antes de agendar.', '''<h2>Onde fica a base do atendimento?</h2><p>O atendimento é realizado por Israel, proprietário do Guará Mix, no Jardim Umarizal, região do Campo Limpo, São Paulo — SP.</p><p>O ponto exato e o horário do atendimento devem ser combinados pelo WhatsApp. Confirme o ponto de atendimento e o horário com Israel antes de se deslocar.</p><h2>Quais regiões são atendidas?</h2><ul><li>Região sul de São Paulo.</li><li>Centro de São Paulo.</li><li>Zona oeste de São Paulo.</li></ul><p>Não há uma lista fechada de bairros. Informe sua localização para combinar o atendimento dentro dessas regiões. A cobertura anunciada se limita à capital de São Paulo.</p><h2>Vocês vão até o cliente?</h2><p>Há atendimento no local do cliente com taxa de motoboy. A disponibilidade e o valor são combinados antes pelo WhatsApp. Esse custo deve ser confirmado separadamente do desconto aplicado ao valor dos cartões.</p><h2>Qual é a antecedência?</h2><p>Agende com no mínimo 3 dias de antecedência. As taxas apresentadas consideram agendamento; sem agendamento, a taxa é maior e precisa ser consultada.</p><h2>O que informar ao combinar o local?</h2><p>Envie a região, o ponto pretendido e a data desejada junto com a bandeira, modalidade e valor dos cartões. Israel confirma se é possível realizar o atendimento e quais são as condições.</p><p>Veja <a href="/como-funciona/">o passo a passo</a> e <a href="/taxas/">a tabela de taxas</a> antes de agendar.</p>''')
page('sobre','Quem atende: Israel e Guará Mix','Guará Tickets: atendimento com Israel, do Guará Mix','Conheça a relação entre o nome Guará Tickets, este site e o atendimento realizado no Jardim Umarizal/Campo Limpo.', '''<h2>Quem realiza o atendimento?</h2><p>Israel, proprietário do Guará Mix, é o responsável pelo atendimento divulgado neste site. A Guará Tickets é a marca usada aqui para apresentar as informações sobre cartões, taxas, simulação e agendamento.</p><h2>Qual é a relação com o mercado?</h2><p>A base informada para o atendimento é o Guará Mix, no Jardim Umarizal, na região do Campo Limpo, capital de São Paulo. Os nomes aparecem juntos para deixar claro quem atende e onde está a base da operação.</p><h2>Como falar com Israel?</h2><p>O contato divulgado é <a href="tel:+5511940240988">(11) 94024-0988</a>. Use o WhatsApp para confirmar modalidade do cartão, valores, local e condições antes do agendamento.</p><h2>Quais informações estão disponíveis?</h2><p>O site reúne <a href="/taxas/">taxas e exemplos de cálculo</a>, <a href="/como-funciona/">etapas do atendimento</a> e <a href="/atendimento-sao-paulo/">regiões atendidas</a>. As informações comerciais estão sujeitas a confirmação, como indicado na página de <a href="/condicoes/">condições</a>.</p><p>Use o contato divulgado no site para esclarecer dúvidas e confirmar o combinado antes do atendimento.</p>''')
page('condicoes','Condições do atendimento: taxas, Pix e agendamento','Condições informadas para o atendimento','Confira as condições comerciais divulgadas pela Guará Tickets e o que precisa ser combinado diretamente com Israel.', '''<h2>Confirmação antes do atendimento</h2><p>O site apresenta informações e estimativas. Bandeira, modalidade, disponibilidade, valores e condições devem ser confirmados com Israel pelo WhatsApp antes de agendar. Não há contratação, aprovação ou pagamento automático pelo site.</p><h2>Alimentação e refeição</h2><p>A taxa considera o valor total dos cartões do atendimento: 17% até R$ 1.000,00; 16% de R$ 1.000,01 a R$ 2.000,00; e 15% acima de R$ 2.000,00. <a href="/taxas/">Veja a tabela e os exemplos.</a></p><h2>Outros benefícios e cartão de crédito</h2><p>A taxa anunciada para outros benefícios é 15%, sujeita à modalidade e confirmação. Para cartão de crédito, os 15% são descontados do valor bruto passado: R$ 1.000,00 de bruto resultam em R$ 850,00 líquidos.</p><p>O desconto descrito no site não explica, por si só, condições de parcelamento, vencimentos ou encargos do cartão. Confirme as condições completas com Israel antes do atendimento. Confirme todos os valores e condições antes de concordar com o atendimento.</p><h2>Agendamento</h2><p>As taxas apresentadas consideram agendamento com no mínimo 3 dias de antecedência. Sem agendamento, a taxa é maior e deve ser consultada. Valores anunciados estão sujeitos a alteração; confirme antes de combinar o atendimento.</p><h2>Pagamento e deslocamento</h2><p>O pagamento é feito no ato, somente via Pix. Atendimento no local do cliente tem taxa de motoboy, com disponibilidade e valor combinados previamente. A cobertura é somente região sul, centro e zona oeste da capital de São Paulo.</p><h2>Contato e ajustes no combinado</h2><p>Para dúvidas ou para alterar o que foi combinado, fale com Israel no WhatsApp <a href="https://wa.me/5511940240988">(11) 94024-0988</a>. Combine previamente com Israel como proceder se precisar alterar ou cancelar o atendimento.</p>''')
page('privacidade','Privacidade: simulador, WhatsApp e atendimento','Como os dados são usados neste site','Este aviso descreve o funcionamento atual do simulador, dos links de contato e dos serviços externos usados para acessar o atendimento.', '''<h2>Dados inseridos no simulador</h2><p>O simulador solicita a categoria do cartão e um valor. O cálculo é executado no navegador, sem um formulário de cadastro ou envio automático para um banco de dados próprio do site.</p><p>Não há campos para número de cartão, senha, código de segurança, CPF, foto de documento ou chave Pix. Não insira essas informações no campo de valor.</p><h2>Ao abrir o WhatsApp</h2><p>Alguns botões abrem um link para o WhatsApp com uma mensagem preenchida. No botão da simulação, essa mensagem pode conter a categoria, o valor bruto, a taxa estimada e o valor líquido. Ao abrir o link, essas informações passam a integrar a navegação para o serviço externo.</p><p>Revise a mensagem antes de enviá-la ao contato. A conversa e o tratamento de dados no WhatsApp também seguem as práticas da plataforma. <a href="https://www.whatsapp.com/legal/privacy-policy" target="_blank" rel="noopener">Consulte a política de privacidade do WhatsApp.</a></p><h2>Dados técnicos da navegação</h2><p>O site é hospedado na Vercel. A hospedagem pode tratar registros técnicos e usar recursos de segurança, como dados de conexão e cookies necessários ao funcionamento. Isso é diferente dos valores usados localmente no simulador.</p><p>O código atual do site não inclui formulário de cadastro, pixel publicitário ou ferramenta própria de análise de visitantes. Se novos recursos de coleta forem adicionados, este aviso deve ser atualizado.</p><h2>Contato sobre dados do atendimento</h2><p>Para perguntas ou solicitações relacionadas às informações que você enviou durante o atendimento, fale com Israel pelo WhatsApp <a href="https://wa.me/5511940240988">(11) 94024-0988</a>, identificando sua solicitação. Não envie documentos ou dados de cartão apenas para usar o simulador.</p><p>Este aviso descreve os recursos atuais do site. Condições específicas de guarda e tratamento dos dados da conversa devem ser esclarecidas com o responsável pelo atendimento.</p>''')
PAGES['/taxas/']={'title':'Taxas e simulador de cartões em São Paulo | Guará Tickets','h1':'Taxas dos cartões e simulador do valor a receber','desc':'Confira as faixas de 17%, 16% e 15%, entenda o desconto sobre o valor bruto e simule quanto recebe após a taxa.','main':hero('Taxas dos cartões e simulador do valor a receber','Confira a tabela anunciada, veja exemplos e faça uma estimativa antes de confirmar o atendimento com Israel.','Taxas e simulador')+'<div class="page-body"><div class="wrap">'+extract('taxas')+extract('simulador')+'<div class="prose"><h2>Como o desconto é calculado?</h2><p>Valor líquido = valor bruto − (valor bruto × taxa ÷ 100). Para alimentação e refeição, o total dos cartões define uma única faixa, aplicada a todo o valor informado.</p>'+examples+'<h2>O que o simulador não inclui?</h2><p>O simulador usa as taxas anunciadas com agendamento. Ele não inclui a taxa de motoboy nem uma eventual taxa maior para atendimento sem agendamento. Esses valores são confirmados com Israel.</p><h2>Exemplo de cartão de crédito</h2><p>A taxa anunciada nessa modalidade é 15% do valor bruto: R$ 1.000,00 passados resultam em R$ 150,00 de desconto e R$ 850,00 recebidos. O simulador acima não confirma as condições do cartão de crédito.</p><p>Leia as <a href="/condicoes/">condições do atendimento</a> e veja <a href="/como-funciona/">como agendar</a>.</p></div></div></div>','calc':True}
PAGES['/duvidas/']={'title':'Dúvidas sobre cartões, taxas e atendimento | Guará Tickets','h1':'Dúvidas sobre cartões, taxas e atendimento','desc':'Respostas sobre modalidades, cálculo, agendamento de 3 dias, Pix e atendimento em São Paulo com Israel.','main':hero('Dúvidas sobre cartões, taxas e atendimento','Abra as perguntas para conferir informações sobre a consulta, os valores e o agendamento.','Dúvidas')+prose('<h2>Cartões, valores e atendimento</h2>'+''.join(faq)+'<h2>Quer conferir um exemplo?</h2><p>Veja a página de <a href="/taxas/">taxas e simulação</a>. Para informações sobre os dados da simulação e links de contato, consulte <a href="/privacidade/">privacidade</a>.</p>'),'calc':False}
